const tabId = 2052873120;
await tool.navigate({ tabId, url: "https://www.lecreuset.com/round-dutch-oven/21177US.html" });
await tool.wait_for({ tabId, condition: "load_state", value: "load" });

// Click Sea Salt and see available sizes
const result = await browserjs(tabId, async () => {
  // Find Sea Salt button
  const seaSaltBtn = document.querySelector('button.color-attribute[data-display-value="Sea Salt"]');
  if (seaSaltBtn) {
    seaSaltBtn.click();
  }
  // Wait a moment for variation to update
  await new Promise(r => setTimeout(r, 1500));

  // Check available sizes
  const sizeButtons = Array.from(document.querySelectorAll('.size-attribute, [data-attr="size"] button, [data-attr="size"] a, .attribute-size a, .attribute-size button'));

  return {
    clicked: !!seaSaltBtn,
    url: window.location.href,
    sizes: sizeButtons.map(b => ({
      text: b.innerText.trim(),
      disabled: b.classList.contains('disabled') || b.getAttribute('aria-disabled') === 'true' || b.disabled,
      selected: b.classList.contains('selected') || b.getAttribute('aria-checked') === 'true'
    }))
  };
});

console.log("Sea Salt result:", JSON.stringify(result, null, 2));

