const tabId = 2052873120;

// Also check Thyme and Olive
const checkColors = await browserjs(tabId, async () => {
  const checkColor = async (colorName) => {
    const btn = document.querySelector(`button.color-attribute[data-display-value="${colorName}"]`);
    if (!btn) return { found: false };
    btn.click();
    await new Promise(r => setTimeout(r, 1200));

    // Check 5.5 qt button
    const size55 = Array.from(document.querySelectorAll('.size-attribute, [data-attr="size"] button, [data-attr="size"] a, .attribute-size a, .attribute-size button'))
      .find(el => el.innerText.includes('5.5 qt'));

    return {
      found: true,
      size55Text: size55 ? size55.innerText.trim() : null,
      size55Disabled: size55 ? (size55.classList.contains('disabled') || size55.getAttribute('aria-disabled') === 'true' || size55.disabled || size55.innerText.includes('Out of Stock')) : null
    };
  };

  const seaSalt = await checkColor('Sea Salt');
  const thyme = await checkColor('Thyme');
  const olive = await checkColor('Olive');

  // Reselect Sea Salt so it's active on the page
  await checkColor('Sea Salt');

  return { seaSalt, thyme, olive };
});

console.log("Green colors availability for 5.5 qt:", JSON.stringify(checkColors, null, 2));

