const tabId = 2052873121;
await tool.navigate({ tabId, url: "https://www.youtube.com/watch?v=a3HTscYo8pE" });
await tool.wait_for({ tabId, condition: "load_state", value: "load" });

// Wait a bit for player to initialize
await tool.wait_for({ tabId, condition: "selector_visible", value: "video", timeout_ms: 10000 });

// Make sure video is playing
const playStatus = await browserjs(tabId, async () => {
  const video = document.querySelector('video');
  if (!video) return { error: "No video element found" };

  // Unmute or play
  try {
    if (video.paused) {
      await video.play();
    }
